//! スナップショットを構成する、システム状態の収集。

mod adapters;
mod dns_config;
mod routes;
mod traceroute;

use crate::config::CollectorSpec;
use anyhow::Result;
use serde_json::{Map, Value, json};

pub use routes::default_gateway;

fn collect(spec: &CollectorSpec) -> Result<Value> {
    match spec {
        CollectorSpec::Adapters => adapters::collect(),
        CollectorSpec::Routes => routes::collect(),
        CollectorSpec::DnsConfig => dns_config::collect(),
        CollectorSpec::Traceroute(target) => traceroute::collect(target),
    }
}

/// 全 collector を並列に実行する。個別の失敗はスナップショット内に記録して続行する
pub fn take_snapshot(specs: &[CollectorSpec], taken_at: i64) -> Value {
    take_snapshot_with(specs, taken_at, collect)
}

/// `collect` で各 collector を実行する。panic も失敗として記録する。
/// 結果から落とすと、全 collector が成功した取得に見えてしまう
fn take_snapshot_with(
    specs: &[CollectorSpec],
    taken_at: i64,
    collect: fn(&CollectorSpec) -> Result<Value>,
) -> Value {
    let results: Vec<(String, Value)> = std::thread::scope(|scope| {
        let handles: Vec<_> = specs
            .iter()
            .map(|spec| (spec.name(), scope.spawn(move || collect(spec))))
            .collect();
        handles
            .into_iter()
            .map(|(name, handle)| {
                let result = handle
                    .join()
                    .unwrap_or_else(|_| Err(anyhow::anyhow!("collector panicked")));
                match result {
                    Ok(data) => (name, json!({ "ok": true, "data": data })),
                    Err(error) => {
                        log::warn!("collector {name} failed: {error:#}");
                        (name, json!({ "ok": false, "error": format!("{error:#}") }))
                    }
                }
            })
            .collect()
    });
    let collectors: Map<String, Value> = results.into_iter().collect();
    json!({ "taken_at": taken_at, "collectors": collectors })
}

/// 失敗した collector の名前を返す
pub fn failed_collectors(snapshot: &Value) -> Vec<String> {
    snapshot["collectors"]
        .as_object()
        .into_iter()
        .flatten()
        .filter(|(_, result)| result["ok"] != Value::Bool(true))
        .map(|(name, _)| name.clone())
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_failing_collector_does_not_lose_the_others() {
        let specs = [
            CollectorSpec::DnsConfig,
            // 不正な宛先でも snapshot 全体は成立する
            CollectorSpec::Traceroute("kuda.invalid".to_string()),
        ];
        let snapshot = take_snapshot(&specs, 42);
        assert_eq!(snapshot["taken_at"], 42);
        assert!(snapshot["collectors"].get("dns_config").is_some());
        assert!(
            snapshot["collectors"]
                .get("traceroute:kuda.invalid")
                .is_some()
        );
    }

    #[test]
    fn a_panicking_collector_is_recorded_as_failed() {
        fn collect(spec: &CollectorSpec) -> Result<Value> {
            match spec {
                CollectorSpec::Routes => panic!("boom"),
                _ => Ok(json!([])),
            }
        }
        let specs = [CollectorSpec::Routes, CollectorSpec::DnsConfig];
        let snapshot = take_snapshot_with(&specs, 42, collect);
        assert_eq!(snapshot["collectors"]["routes"]["ok"], false);
        assert_eq!(
            snapshot["collectors"]["routes"]["error"],
            "collector panicked"
        );
        assert_eq!(snapshot["collectors"]["dns_config"]["ok"], true);
        assert_eq!(failed_collectors(&snapshot), ["routes"]);
    }

    #[test]
    fn reports_failed_collectors() {
        let snapshot = json!({ "collectors": {
            "a": { "ok": true, "data": 1 },
            "b": { "ok": false, "error": "x" },
        }});
        assert_eq!(failed_collectors(&snapshot), ["b"]);
    }
}
//! スナップショットの取得履歴と、collector ごとの比較基準（last_known_good）。

use super::Store;
use anyhow::Result;
use rusqlite::{Connection, OptionalExtension, Transaction, TransactionBehavior, params};
use serde_json::{Value, json};

impl Store {
    /// 正常時に取得したスナップショットを記録する。取得履歴には失敗した collector も
    /// そのまま残し、新しい `keep` 件だけを残す。比較基準は成功した collector の分だけを
    /// 置き換え、失敗した collector は前回までの成功データを使い続ける。
    /// 全 collector が成功したときだけ、取得時刻を `last_complete_snapshot` にも記録する
    pub fn record_snapshot(&self, watch: &str, ts: i64, snapshot: &Value, keep: u32) -> Result<()> {
        let tx = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        tx.execute(
            "INSERT INTO snapshots (watch, ts, data) VALUES (?1, ?2, ?3)",
            params![watch, ts, snapshot.to_string()],
        )?;
        tx.execute(
            "DELETE FROM snapshots WHERE watch = ?1 AND rowid NOT IN (
                 SELECT rowid FROM snapshots WHERE watch = ?1
                 ORDER BY ts DESC, rowid DESC LIMIT ?2
             )",
            params![watch, keep],
        )?;
        let mut complete = true;
        for (name, result) in snapshot["collectors"].as_object().into_iter().flatten() {
            if result["ok"] != Value::Bool(true) {
                complete = false;
                continue;
            }
            // check と snapshot が並行したとき、収集開始の早い側が後から完了しても戻さない
            tx.execute(
                "INSERT INTO known_good (watch, collector, ts, data) VALUES (?1, ?2, ?3, ?4)
                 ON CONFLICT (watch, collector) DO UPDATE SET ts = excluded.ts, data = excluded.data
                 WHERE excluded.ts >= known_good.ts",
                params![watch, name, ts, result["data"].to_string()],
            )?;
        }
        Self::update_last_snapshot(&tx, watch, ts, complete)?;
        tx.commit()?;
        Ok(())
    }

    /// `collectors` それぞれの最後の成功データをまとめた、比較基準のスナップショット。
    /// collector ごとに取得時刻が異なるので、時刻は各 collector の `taken_at` に持つ。
    /// どれも成功したことがなければ None
    pub fn last_known_good(&self, watch: &str, collectors: &[String]) -> Result<Option<Value>> {
        let mut statement = self
            .conn
            .prepare("SELECT ts, data FROM known_good WHERE watch = ?1 AND collector = ?2")?;
        let mut merged = serde_json::Map::new();
        for name in collectors {
            let row: Option<(i64, String)> = statement
                .query_row(params![watch, name], |row| Ok((row.get(0)?, row.get(1)?)))
                .optional()?;
            if let Some((ts, data)) = row {
                let data: Value = serde_json::from_str(&data)?;
                merged.insert(
                    name.clone(),
                    json!({ "ok": true, "taken_at": ts, "data": data }),
                );
            }
        }
        Ok((!merged.is_empty()).then(|| json!({ "collectors": merged })))
    }

    /// last_snapshot・last_snapshot_complete と、`complete` なら last_complete_snapshot だけを
    /// 更新する。check と snapshot のどちらからも呼ばれるので、他の列は読み込んだ時点の値で
    /// 上書きしない。後から完了した側の収集開始が早いこともあるので、時刻は戻さない。
    /// 同じ秒の取得が重なったら、どちらかが失敗していれば失敗とする
    fn update_last_snapshot(conn: &Connection, watch: &str, ts: i64, complete: bool) -> Result<()> {
        // SET の右辺の列名は、どれも更新前の値を指す
        conn.execute(
            "INSERT INTO watch_state
                 (watch, last_snapshot, last_complete_snapshot, last_snapshot_complete, streak, active)
             VALUES (?1, ?2, ?3, ?4, 0, 0)
             ON CONFLICT (watch) DO UPDATE SET
                 last_snapshot =
                     max(coalesce(last_snapshot, excluded.last_snapshot), excluded.last_snapshot),
                 last_complete_snapshot = max(
                     coalesce(last_complete_snapshot, excluded.last_complete_snapshot),
                     coalesce(excluded.last_complete_snapshot, last_complete_snapshot)
                 ),
                 last_snapshot_complete = CASE
                     WHEN last_snapshot IS NULL OR excluded.last_snapshot > last_snapshot
                         THEN excluded.last_snapshot_complete
                     WHEN excluded.last_snapshot = last_snapshot
                         THEN last_snapshot_complete AND excluded.last_snapshot_complete
                     ELSE last_snapshot_complete
                 END",
            params![watch, ts, complete.then_some(ts), complete],
        )?;
        Ok(())
    }

    /// 全 collector が成功した取得として時刻だけを記録する
    #[cfg(test)]
    pub fn set_last_snapshot(&self, watch: &str, ts: i64) -> Result<()> {
        Self::update_last_snapshot(&self.conn, watch, ts, true)
    }
}

