1	//! 事件ディレクトリ（現在のスナップショット、正常時との差分、メトリクス）の生成。
2	
3	mod diff;
4	
5	use crate::baseline::{SeriesStats, Source};
6	use crate::paths::{create_private_dir, is_safe_name};
7	use crate::probe::ProbeRun;
8	use crate::store::MetricRow;
9	use crate::time::format_time;
10	use anyhow::{Context, Result, ensure};
11	use chrono::{Local, TimeZone};
12	use diff::{collector_names, render_diff};
13	use serde::{Deserialize, Serialize};
14	use serde_json::Value;
15	use std::fmt::Write as _;
16	use std::path::{Path, PathBuf};
17	
18	const META_FILE: &str = "incident.json";
19	
20	#[derive(Debug, Clone, Serialize, Deserialize)]
21	pub struct Incident {
22	    pub watch: String,
23	    pub id: String,
24	    pub created: i64,
25	    pub since: i64,
26	    #[serde(skip)]
27	    pub dir: PathBuf,
28	}
29	
30	pub struct Evidence<'a> {
31	    pub watch: &'a str,
32	    pub reason: &'a str,
33	    pub since: i64,
34	    pub run: &'a ProbeRun,
35	    pub stats: &'a [SeriesStats],
36	    pub history: &'a [MetricRow],
37	    pub current: &'a Value,
38	    /// collector ごとの最後の成功データ（`Store::last_known_good`）
39	    pub last_good: Option<&'a Value>,
40	}
41	
42	/// 秒単位の時刻から一意なディレクトリを作る。同じ秒に重なったら連番を付ける
43	fn create_unique_dir(parent: &Path, created: i64) -> Result<(String, PathBuf)> {
44	    create_private_dir(parent)?;
45	    let base = Local.timestamp_opt(created, 0).single().map_or_else(
46	        || created.to_string(),
47	        |time| time.format("%Y%m%d-%H%M%S").to_string(),
48	    );
49	    for attempt in 1..100 {
50	        let id = match attempt {
51	            1 => base.clone(),
52	            n => format!("{base}-{n}"),
53	        };
54	        let dir = parent.join(&id);
55	        if !dir.exists() {
56	            create_private_dir(&dir)?;
57	            return Ok((id, dir));
58	        }
59	    }
60	    anyhow::bail!("too many incidents at {base}");
61	}
62	
63	pub fn create(incidents_dir: &Path, evidence: &Evidence, created: i64) -> Result<Incident> {
64	    let (id, dir) = create_unique_dir(&incidents_dir.join(evidence.watch), created)?;
65	    let incident = Incident {
66	        watch: evidence.watch.to_string(),
67	        id,
68	        created,
69	        since: evidence.since,
70	        dir,
71	    };
72	    let write = |name: &str, contents: String| {
73	        let path = incident.dir.join(name);
74	        std::fs::write(&path, contents).with_context(|| format!("failed to write {name}"))
75	    };
76	    write("summary.md", render_summary(evidence, created))?;
77	    write("diff.md", render_diff(evidence.last_good, evidence.current))?;
78	    write(
79	        "current.json",
80	        serde_json::to_string_pretty(evidence.current)?,
81	    )?;
82	    if let Some(data) = evidence.last_good {
83	        write("last_known_good.json", serde_json::to_string_pretty(data)?)?;
84	    }
85	    write("metrics.csv", render_metrics(evidence))?;
86	    write(META_FILE, serde_json::to_string_pretty(&incident)?)?;
87	    Ok(incident)
88	}
89	
90	/// create_unique_dir が付ける形の id（時刻と連番）か。英字を通さないので
91	/// `-recovered` の回復レポートや Windows の予約名（NUL など）と重ならない
92	fn is_incident_id(id: &str) -> bool {
93	    !id.is_empty() && id.chars().all(|c| c.is_ascii_digit() || c == '-')
94	}
95	
96	pub fn load(dir: &Path) -> Result<Incident> {
97	    let path = dir.join(META_FILE);
98	    let text = std::fs::read_to_string(&path)
99	        .with_context(|| format!("failed to read {}", path.display()))?;
100	    let mut incident: Incident = serde_json::from_str(&text)?;
101	    // watch と id はレポートの保存先パスに使う。他人から受け取った事件でも外へ書かせない
102	    ensure!(
103	        is_safe_name(&incident.watch),
104	        "{} has an invalid watch: {:?}",
105	        path.display(),
106	        incident.watch
107	    );
108	    ensure!(
109	        is_incident_id(&incident.id),
110	        "{} has an invalid id: {:?}",
111	        path.display(),
112	        incident.id
113	    );
114	    incident.dir = dir.to_path_buf();
115	    Ok(incident)
116	}
117	
118	/// 保持期間を過ぎた事件ディレクトリを削除する
119	pub fn prune(incidents_dir: &Path, retention_days: u32, now: i64) -> Result<()> {
120	    let cutoff = now - i64::from(retention_days) * 86400;
121	    for watch_dir in std::fs::read_dir(incidents_dir)? {
122	        let watch_dir = watch_dir?.path();
123	        if !watch_dir.is_dir() {
124	            continue;
125	        }
126	        for entry in std::fs::read_dir(&watch_dir)? {
127	            let dir = entry?.path();
128	            if load(&dir).is_ok_and(|incident| incident.created < cutoff) {
129	                std::fs::remove_dir_all(&dir)
130	                    .with_context(|| format!("failed to remove {}", dir.display()))?;
131	            }
