                target: "192.0.2.1:443".to_string(),
                ok: false,
                rtt_ms: None,
                value: None,
                error: Some("timed | out".to_string()),
            }],
        }
    }

    fn evidence<'a>(
        run: &'a ProbeRun,
        current: &'a Value,
        history: &'a [MetricRow],
    ) -> Evidence<'a> {
        Evidence {
            watch: "w",
            reason: "loss >= 0.5",
            since: 900,
            run,
            stats: &[],
            history,
            current,
            last_good: None,
        }
