93	pub(super) fn render_diff(last_good: Option<&Value>, current: &Value) -> String {
94	    let mut text = "# 正常時との差分\n\n".to_string();
95	    let Some(last_good) = last_good else {
96	        text.push_str("比較できる正常時のスナップショットがありません。\n");
97	        return text;
98	    };
99	    let _ = writeln!(
100	        text,
101	        "基準: {} / 現在: {}\n",
102	        baseline_time(last_good),
103	        current["taken_at"]
104	            .as_i64()
105	            .map_or_else(|| "?".to_string(), format_time),
106	    );
107	
108	    let mut names = collector_names(last_good);
109	    names.extend(collector_names(current));
110	    names.sort();
111	    names.dedup();
112	
113	    let (mut changed, mut added, mut removed, mut failed) =
114	        (Vec::new(), Vec::new(), Vec::new(), Vec::new());
115	    for name in names {
116	        let (Some(old), Some(new)) = (
117	            collector_data(last_good, &name),
118	            collector_data(current, &name),
119	        ) else {
120	            // 片方で取得できていないと全項目が差分に見えるので、1 行にまとめる
121	            let error = match current["collectors"][&name]["error"].as_str() {
122	                Some(error) => error,
123	                None if current["collectors"].get(&name).is_none() => {
124	                    "現在のスナップショットに含まれていません"
125	                }
126	                None => "正常時に取得に成功したことがありません",
127	            };
128	            failed.push(format!("- `{name}`: {error}"));
129	            continue;
130	        };
131	        for (path, value) in &new {
132	            match old.get(path) {
133	                None => added.push(format!("- `{path}`: {value}")),
134	                Some(previous) if previous != value => {
135	                    changed.push(format!("- `{path}`: {previous} ⇒ {value}"));
136	                }
137	                Some(_) => {}
138	            }
139	        }
140	        for (path, value) in &old {
141	            if !new.contains_key(path) {
142	                removed.push(format!("- `{path}`: {value}"));
143	            }
144	        }
145	    }
146	
147	    if changed.is_empty() && added.is_empty() && removed.is_empty() && failed.is_empty() {
148	        text.push_str("差分はありません。\n");
149	    }
150	    for (heading, lines) in [
151	        ("変更", changed),
152	        ("追加", added),
153	        ("削除", removed),
154	        ("比較できなかった項目", failed),
155	    ] {
156	        if !lines.is_empty() {
157	            let _ = writeln!(text, "## {heading}\n\n{}\n", lines.join("\n"));
158	        }
159	    }
160	    text
161	}
