30	pub struct Evidence<'a> {
31	    pub watch: &'a str,
32	    pub reason: &'a str,
33	    pub since: i64,
34	    pub run: &'a ProbeRun,
35	    pub stats: &'a [SeriesStats],
36	    pub history: &'a [MetricRow],
37	    pub current: &'a Value,
38	    /// collector ごとの最後の成功データ（`Store::last_known_good`）
39	    pub last_good: Option<&'a Value>,
