42	/// 秒単位の時刻から一意なディレクトリを作る。同じ秒に重なったら連番を付ける
43	fn create_unique_dir(parent: &Path, created: i64) -> Result<(String, PathBuf)> {
44	    create_private_dir(parent)?;
45	    let base = Local.timestamp_opt(created, 0).single().map_or_else(
46	        || created.to_string(),
47	        |time| time.format("%Y%m%d-%H%M%S").to_string(),
48	    );
49	    for attempt in 1..100 {
50	        let id = match attempt {
51	            1 => base.clone(),
52	            n => format!("{base}-{n}"),
53	        };
54	        let dir = parent.join(&id);
55	        if !dir.exists() {
56	            create_private_dir(&dir)?;
57	            return Ok((id, dir));
58	        }
59	    }
60	    anyhow::bail!("too many incidents at {base}");
61	}
62	
63	pub fn create(incidents_dir: &Path, evidence: &Evidence, created: i64) -> Result<Incident> {
64	    let (id, dir) = create_unique_dir(&incidents_dir.join(evidence.watch), created)?;
65	    let incident = Incident {
66	        watch: evidence.watch.to_string(),
67	        id,
68	        created,
69	        since: evidence.since,
70	        dir,
71	    };
72	    let write = |name: &str, contents: String| {
73	        let path = incident.dir.join(name);
74	        std::fs::write(&path, contents).with_context(|| format!("failed to write {name}"))
75	    };
76	    write("summary.md", render_summary(evidence, created))?;
77	    write("diff.md", render_diff(evidence.last_good, evidence.current))?;
78	    write(
79	        "current.json",
80	        serde_json::to_string_pretty(evidence.current)?,
81	    )?;
82	    if let Some(data) = evidence.last_good {
83	        write("last_known_good.json", serde_json::to_string_pretty(data)?)?;
84	    }
85	    write("metrics.csv", render_metrics(evidence))?;
86	    write(META_FILE, serde_json::to_string_pretty(&incident)?)?;
87	    Ok(incident)
88	}
