146	fn render_summary(evidence: &Evidence, created: i64) -> String {
147	    let mut text = String::new();
148	    let _ = writeln!(text, "# 事件サマリ: {}\n", evidence.watch);
149	    let _ = writeln!(text, "- 検出時刻: {}", format_time(created));
150	    let _ = writeln!(text, "- 発生開始: {}", format_time(evidence.since));
151	    let _ = writeln!(text, "- 理由: {}", evidence.reason);
152	    let _ = writeln!(text, "- OS: {}", std::env::consts::OS);
153	
154	    text.push_str("\n## 現在の指標\n\n| 指標 | 値 |\n| --- | --- |\n");
155	    for (name, value) in evidence.run.metrics() {
156	        let _ = writeln!(text, "| {name} | {value:.3} |");
157	    }
158	
159	    text.push_str(
160	        "\n## ターゲット別の結果\n\n| ターゲット | 結果 | RTT | エラー |\n| --- | --- | --- | --- |\n",
161	    );
162	    for result in &evidence.run.results {
163	        let _ = writeln!(
164	            text,
165	            "| {} | {} | {} | {} |",
166	            cell(&result.target),
167	            if result.ok { "成功" } else { "失敗" },
168	            format_ms(result.rtt_ms),
169	            cell(result.error.as_deref().unwrap_or("-")),
170	        );
171	    }
172	
173	    text.push_str("\n## ベースライン\n\n");
174	    if evidence.stats.is_empty() {
175	        text.push_str("データ不足のため、まだありません。\n");
176	    } else {
177	        text.push_str(
178	            "| 系列 | 集計 | サンプル数 | p50 | p95 |\n| --- | --- | --- | --- | --- |\n",
179	        );
180	        for stat in evidence.stats {
181	            let source = match stat.source {
182	                Source::Bucket => "同時間帯",
183	                Source::Overall => "全体",
184	            };
185	            let _ = writeln!(
186	                text,
187	                "| {} | {source} | {} | {:.3} | {:.3} |",
188	                stat.series, stat.samples, stat.p50, stat.p95
189	            );
190	        }
191	    }
192	
193	    text.push_str("\n## 最後の正常時スナップショット\n\n");
194	    text.push_str("collector ごとに、最後に取得に成功した時点のデータと比べます。\n\n");
195	    let mut names = collector_names(evidence.current);
196	    if let Some(last_good) = evidence.last_good {
197	        names.extend(collector_names(last_good));
198	    }
199	    names.sort();
200	    names.dedup();
201	    if names.is_empty() {
202	        text.push_str("ありません。\n");
203	    }
204	    for name in names {
205	        let taken_at = evidence
206	            .last_good
207	            .and_then(|last_good| last_good["collectors"][&name]["taken_at"].as_i64());
208	        let time = taken_at.map_or_else(|| "成功した取得がありません".to_string(), format_time);
209	        let _ = writeln!(text, "- `{name}`: {time}");
210	    }
211	    text
212	}
213	
214	fn render_metrics(evidence: &Evidence) -> String {
215	    let baseline = |metric: &str| {
216	        let series = match metric {
217	            "rtt_p50" => "rtt",
218	            other => other,
219	        };
220	        let stat = evidence.stats.iter().find(|stat| stat.series == series);
221	        stat.map_or_else(
222	            || ",".to_string(),
223	            |stat| format!("{:.3},{:.3}", stat.p50, stat.p95),
224	        )
225	    };
226	    let mut text = "time,metric,value,baseline_p50,baseline_p95\n".to_string();
227	    for row in evidence.history {
228	        let _ = writeln!(
229	            text,
230	            "{},{},{:.3},{}",
231	            format_time(row.ts),
232	            row.name,
233	            row.value,
234	            baseline(&row.name)
235	        );
236	    }
237	    text
238	}
