319	    fn evidence<'a>(
320	        run: &'a ProbeRun,
321	        current: &'a Value,
322	        history: &'a [MetricRow],
323	    ) -> Evidence<'a> {
324	        Evidence {
325	            watch: "w",
326	            reason: "loss >= 0.5",
