328	            run,
329	            stats: &[],
330	            history,
331	            current,
332	            last_good: None,
333	        }
334	    }
335	
336	    #[test]
337	    fn creates_all_files_and_can_be_reloaded() {
338	        let root = temp_dir("incident");
339	        let run = run();
340	        let current = snapshot(json!([]));
341	        let history = [MetricRow {
342	            ts: 1000,
343	            name: "loss".to_string(),
344	            value: 1.0,
345	        }];
346	        let incident = create(&root, &evidence(&run, &current, &history), 1000).unwrap();
347	
348	        for file in ["summary.md", "diff.md", "current.json", "metrics.csv"] {
349	            assert!(incident.dir.join(file).is_file(), "{file}");
350	        }
351	        assert!(!incident.dir.join("last_known_good.json").exists());
352	        let summary = std::fs::read_to_string(incident.dir.join("summary.md")).unwrap();
353	        assert!(summary.contains("192.0.2.1:443"));
354	        assert!(summary.contains("timed \\| out"));
355	        let csv = std::fs::read_to_string(incident.dir.join("metrics.csv")).unwrap();
356	        assert!(csv.lines().nth(1).unwrap().ends_with(",loss,1.000,,"));
357	
358	        let loaded = load(&incident.dir).unwrap();
359	        assert_eq!(loaded.since, 900);
