                 WHERE excluded.ts >= known_good.ts",
                params![watch, name, ts, result["data"].to_string()],
            )?;
        }
        Self::update_last_snapshot(&tx, watch, ts, complete)?;
        tx.commit()?;
        Ok(())
    }

